"""Record completed wireframes from their audited live Figma inventory."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[1]
TMP=ROOT/'.tmp/complete-wireframes'
DEST=ROOT/'ia/wireframes'
FILE='https://www.figma.com/design/1LeVoicxDT7Sl8TpMPs4hr/Dashboard'
def link(node):return FILE+'?node-id='+node.replace(':','-')
def append_once(path,marker,text):
    original=path.read_text(encoding='utf-8-sig')
    if marker not in original:path.write_text(original.rstrip()+'\n\n'+text.strip()+'\n',encoding='utf-8')

def main():
    audit=json.loads((TMP/'final-audit.json').read_text(encoding='utf-8'))
    meta=json.loads((TMP/'manifest.json').read_text(encoding='utf-8'))
    live={d['name']:d for d in json.loads((TMP/'live-content.json').read_text(encoding='utf-8'))}
    frames={d['name']:d for d in audit['frames']}
    assert len(frames)==48 and not audit['overflow'] and not audit['annotationOverflow']
    assert all(f['navCount'] in (0,10) for f in frames.values())
    for d in meta:
        f=frames[d['name']]
        lines=[f"# {d['name']} — {d['title']}",'',"**Статус:** отрисовано и проверено 21 сентября 2026.",f"**Размер:** {f['width']}×{f['height']} px.",f"**Тип:** {d['kind']}.",f"**Назначение:** {d['title']}.",f"**Вход:** {d['trigger']}.",f"**Figma:** [{d['title']}]({link(f['id'])}).",'']
        if f['navCount']:
            lines+=['## Общая оболочка','','Header 64 px; Sidebar 240 px. Все 10 пунктов видны на постоянных местах. Контекст проекта и исследования указан отдельно; недоступные пункты не скрываются.','']
        lines+=['## Секции сверху вниз','']
        for s in live[d['name']]['sections']:
            if not s['text']:continue
            lines+=[f"### {s['name']} · {round(s['width'])}×{round(s['height'])} px",'']
            lines+=['- '+text.replace('\n',' / ') for text in dict.fromkeys(s['text'])]
            lines+=['']
        lines+=['## Поведение и границы','',f"Поверхность: {d['kind']}. Основание появления: {d['trigger']}.",'','Значения и содержимое прототипов — демонстрационные. Фрейм показывает интерфейс и состояние, не работающий сбор данных или готовый PDF.']
        if d['note']:lines+=['',d['note']]
        if 'Mobile' in d['name']:lines+=['','Это мобильный интерфейс участника теста. Мобильная версия командного дашборда не добавляется.']
        if d['name']=='SharedPatterns':lines+=['','Эта доска не входит в число 47 экранов/состояний продукта.']
        lines+=['','[Полный каталог и ограничения прототипирования](complete-delivery.md).','']
        (DEST/(d['name']+'.md')).write_text('\n'.join(lines),encoding='utf-8')

    labels={d['name']:d['title'] for d in meta}
    labels.update(ResultsOverview='Обзор результатов',Heatmaps='Тепловая карта кликов',Funnel='Воронка',Replay='Запись сессии',SuccessCriteria='Критерий: последовательность',Projects='Создание проекта — центральная модалка',Studies='Исследования проекта',StudySetup='Настройка и подключение прототипа',Launch='Проверка и запуск')
    groups={'20:3':'Основной анализ и критерии','30:2':'Проекты, исследования и запуск','45:2':'Создание и настройка — подробности','45:3':'Прохождение участником на ПК','45:4':'Анализ — подробности и состояния','45:5':'PDF — подготовка и состояния','45:6':'Прохождение участником на мобильном','45:7':'Общие состояния интерфейса'}
    lines=['# Полный набор wireframes','', 'Дата: 21 сентября 2026. **Отрисовка завершена: 47 экранов и состояний, плюс отдельная доска SharedPatterns.** Из них 43 desktop-фрейма 1920×1080 и 4 мобильных фрейма участника 390×844.','',f"[Открыть страницу wireframes]({link('20:2')}). Новые экраны расположены ниже исходных девяти; слои редактируемые.",'','## Что показано','','- Проекты и исследования: заполненные и пустые списки, создание проекта по центру, новый черновик.','- Настройка заданий и свободного изучения, выбор задания, критерии по URL/кнопке/последовательности, подключение, контрольное прохождение и запуск.','- Участник: начало, объяснение записи всего ввода, задание, живой интерфейс с управлением тестом, завершение, недоступность ссылки/прототипа и ошибка передачи.','- Анализ: обзор первым экраном, сценарии, карты всех и первых кликов, динамическое состояние, воронка, участники и детали, четыре сигнала, полная/неполная/недоступная запись.','- PDF: состав и предпросмотр, формирование, готовность и ошибка.','- Общие состояния: загрузка, ошибка, пустая фильтрация, обязательное поле, сохранение и инструкция свободного изучения.','','## Каталог','']
    for sid,title in groups.items():
        lines += [f'### {title}','', '| Экран / состояние | Figma | Описание |','| --- | --- | --- |']
        for name,f in frames.items():
            if f['sectionId']==sid:lines += [f"| {labels[name]} | [{name}]({link(f['id'])}) | [{name}.md]({name}.md) |"]
        lines+=['']
    lines+=['## Проверка','','Проверены границы содержимого всех 48 фреймов и подписи над ними: переполнений нет. На всех командных страницах с Sidebar — 10 пунктов. Снимки экранов просмотрены; после правок отдельно проверены тепловые слои, запись с разрывом, PDF и мобильные экраны. Проверка макетов не заменяет тестирование реализации.','','Модалки создания проекта и выбора задания расположены по центру с затемнением фона. Подключение прототипа и приглашение участников — постоянные блоки. Окно выбора размера на тепловой карте относится к тестируемому прототипу, а не к дашборду.','','## Переходы и ограничения','','Логика: Все проекты → Исследования проекта → Настройка → Проверка/запуск → Обзор результатов → выбранный способ анализа. Карта → участники области → участник → запись; обзор → PDF. Участник: приглашение → инструкция → прохождение заданий → подтверждение передачи.','','**Кликабельный прототип не собран.** Текущий MCP-вызов NAVIGATE отклонён для целевого фрейма внутри Section: инструмент требует top-level frame. Макеты не переносились из секций. Это ограничение текущего вызова, не утверждение общего ограничения Figma. Скрипт переходов сохранён как неподключённая заготовка.','','Состояния не означают новые разделы продукта. Способ входа, привязка событий, правила первого клика/попыток, пороги сигналов, хранение, оболочка прототипа и детали PDF остаются открытыми решениями. Макеты показывают предложенный UX, не подтверждённую техническую реализацию.','','Старые sitemap/user-flow на другой странице Figma относятся к версии до Projects; эта поставка не перерисовывает их.','','## Воспроизведение','','Python-генераторы в execution/: build_wireframes.py, build_project_wireframes.py, build_complete_wireframes.py подготавливают структуры; finish_wireframe_details.py — тепловые слои, курсор, таймлайн и мини-карты PDF; finalize_wireframe_canvas.py — завершающие правки и аудит. После создания: detail-скрипты → final-polish → audit. Перед повторным запуском читать текущий канвас и сопоставлять node ID. Создание защищено от дублей. record_complete_wireframes.py формирует каталог по живому снимку структуры.','','Входные снимки и payloads: .tmp/complete-wireframes. Итоговый перечень узлов: complete-manifest.json. Связи из prototype-links.js не применены.','']
    (DEST/'complete-delivery.md').write_text('\n'.join(lines),encoding='utf-8')
    (DEST/'complete-manifest.json').write_text(json.dumps({'date':'2026-09-21','wireframes':47,'patternsBoards':1,'pageId':'20:2','clickablePrototype':False,**audit},ensure_ascii=False,indent=2),encoding='utf-8')
    append_once(DEST/'README.md','## Полное покрытие — 21 сентября', '## Полное покрытие — 21 сентября 2026\n\nАктуальный результат: **47 экранов и состояний + доска общих паттернов**. [Полный каталог, описания и ссылки на Figma](complete-delivery.md). Выше сохранена история первоначальных поставок на 5 и 9 экранов.\n\nКарты дополнены демонстрационным цветовым слоем, первым кликом и открытым окном прототипа. Мобильный путь участника показан отдельно. Кликабельный прототип не собран; ограничение текущего MCP описано в каталоге.')
    plan=DEST/'coverage-plan.md'
    text=plan.read_text(encoding='utf-8').replace('Статус: предложение по детализации, ещё не отрисовано.','Статус: отрисовано 47 экранов/состояний и доска паттернов. [Итоговый каталог](complete-delivery.md). План ниже сохранён как основание набора; упоминания плейсхолдеров относятся к исходной версии.').replace('## Что уже нарисовано','## Исходный набор до расширения')
    plan.write_text(text,encoding='utf-8')
    for name,update in {'Heatmaps':'Добавлен демонстрационный тепловой слой. Отдельно показаны первый клик и карта центрального окна выбора размера.','Replay':'Добавлены курсор и маркеры событий, подписи времени привязаны к длительности. Неполная и недоступная запись показаны отдельными фреймами.'}.items():
        append_once(DEST/(name+'.md'),'## Уточнение полного пакета',f'## Уточнение полного пакета\n\n{update} [Полный каталог](complete-delivery.md).')
    append_once(ROOT/'directives/directive_wireframes.md','## Практика расширенного набора', '## Практика расширенного набора — 21 сентября 2026\n\n- Общий апрув «на все апрув не спрашивай» и команда дорисовать недостающее действуют для этого проекта; повторные согласования не нужны.\n- Группировать подробный набор по этапам; подписывать тип поверхности и точку входа. Пустое состояние/ошибка не равны новой странице.\n- Над мобильным фреймом резервировать место под двухстрочный заголовок и подпись; проверять их границы отдельно.\n- Подписи времени replay размещать пропорционально времени, не строкой с пробелами. Разрыв записи не должен содержать выдуманных событий.\n- Цвет теплового слоя показывает интенсивность; остальной интерфейс low-fi. Точки демонстрационные.\n- NAVIGATE к фрейму внутри Section в текущем MCP-вызове отклонён как недопустимая destination. Наличие скрипта не подтверждает создание связей.\n- Большие ответы use_figma могут обрезаться и становиться невалидным JSON. Снимки структуры читать порциями по 4 фрейма и проверять каждую порцию.\n- Итоговый реестр узлов и аудит: complete-manifest.json; актуальный обзор: complete-delivery.md.')
    assert all((DEST/(n+'.md')).exists() for n in frames)
    print(json.dumps({'wireframes':47,'patternsBoards':1,'newDescriptions':len(meta),'overflow':0,'catalog':str(DEST/'complete-delivery.md')},ensure_ascii=False))
if __name__=='__main__':main()
